/* Admin Grouped Searchable Destination Picker (CR-2026-11-26-001) */
.admin-picker-container {
  position: relative;
}

.admin-picker-relative-wrap {
  position: relative;
  width: 100%;
}

.admin-picker-trigger {
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  width: 100% !important;
  height: 42px;
  padding: 10px 14px;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  color: #475569;
  cursor: pointer;
  text-align: left;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.admin-picker-trigger:hover {
  background: #e2e8f0;
  border-color: #cbd5e1;
}

.admin-picker-trigger:focus,
.admin-picker-trigger.open {
  outline: none;
  background: #f8fafc;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.12);
}

.admin-picker-selected-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  padding-right: 8px;
  flex: 1;
}

.admin-picker-chevron {
  font-size: 16px;
  color: #64748b;
  flex-shrink: 0;
  transition: transform 0.2s ease;
}

.admin-picker-chevron.rotate {
  transform: rotate(180deg);
  color: #3b82f6;
}

.admin-picker-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  width: 100%;
  min-width: 240px;
  z-index: 60;
  background: #ffffff;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.14), 0 8px 10px -6px rgba(15, 23, 42, 0.08);
  overflow: hidden;
}

.admin-picker-search-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
}

.admin-picker-search-icon {
  font-size: 16px;
  color: #94a3b8;
  flex-shrink: 0;
}

.admin-picker-search-input {
  width: 100%;
  border: none;
  background: transparent;
  font-size: 13px;
  color: #1e293b;
  outline: none;
  font-family: inherit;
}

.admin-picker-search-input::placeholder {
  color: #94a3b8;
}

.admin-picker-search-clear {
  background: none;
  border: none;
  padding: 0;
  color: #94a3b8;
  cursor: pointer;
  display: flex;
  align-items: center;
  font-size: 16px;
  transition: color 0.15s ease;
}

.admin-picker-search-clear:hover {
  color: #64748b;
}

.admin-picker-list {
  max-height: 220px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 4px 0;
}

.admin-picker-group-header {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #f8fafc;
  padding: 6px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #f1f5f9;
  border-bottom: 1px solid #f1f5f9;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #64748b;
}

.admin-picker-group-badge {
  font-size: 10px;
  font-weight: 600;
  color: #94a3b8;
  background: #e2e8f0;
  padding: 1px 6px;
  border-radius: 9999px;
}

.admin-picker-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  min-height: 38px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  color: #334155;
  transition: background 0.15s ease, color 0.15s ease;
}

.admin-picker-item:hover {
  background: #f1f5f9;
  color: #0f172a;
}

.admin-picker-item.selected {
  background: #eff6ff;
  color: #1d4ed8;
  font-weight: 600;
}

.admin-picker-item-content {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.admin-picker-group-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.admin-picker-group-dot.static-pages { background: #94a3b8; }
.admin-picker-group-dot.categories { background: #3b82f6; }
.admin-picker-group-dot.items { background: #f59e0b; }

.admin-picker-item-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.admin-picker-check-icon {
  font-size: 16px;
  color: #3b82f6;
  flex-shrink: 0;
  margin-left: 8px;
}

.admin-picker-loading,
.admin-picker-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px 16px;
  color: #64748b;
  font-size: 13px;
}

.admin-picker-empty {
  color: #94a3b8;
}

.admin-picker-empty-icon {
  font-size: 24px;
  opacity: 0.5;
}

.admin-picker-spinner {
  width: 20px;
  height: 20px;
  border: 2px solid #e2e8f0;
  border-top-color: #3b82f6;
  border-radius: 50%;
  animation: adminPickerSpin 0.7s linear infinite;
}

@keyframes adminPickerSpin {
  to { transform: rotate(360deg); }
}

.admin-picker-path-preview {
  margin-top: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  color: #64748b;
}

.admin-path-text {
  color: #3b82f6;
  word-break: break-all;
}
